// Normaliza as vagas da API pública da Gupy e aplica os filtros da configuração.
// Roda dentro de um nó Code do n8n (o build injeta este arquivo) e nos testes com node --test.

const MODELOS = { remote: "remoto", hybrid: "hibrido", "on-site": "presencial" };

function semAcento(texto) {
  return (texto || "").normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();
}

function normalizarVaga(bruta) {
  return {
    id: bruta.id,
    titulo: (bruta.name || "").trim(),
    empresa: (bruta.careerPageName || "").trim(),
    modelo: MODELOS[bruta.workplaceType] || bruta.workplaceType || "",
    cidade: bruta.city || "",
    estado: bruta.state || "",
    publicada: bruta.publishedDate,
    prazo: bruta.applicationDeadline || null,
    link: bruta.jobUrl,
    descricao: bruta.description || "",
  };
}

// Um termo casa como palavra inteira ("sr" não pode barrar "srta" nem "sre").
function contemTermo(texto, termo) {
  const t = semAcento(termo).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return new RegExp(`(^|[^a-z0-9])${t}([^a-z0-9]|$)`).test(semAcento(texto));
}

// Retorna as vagas aprovadas e a contagem de descartes por motivo, para o resumo ser auditável.
function filtrarVagas(respostas, cfg, agora = new Date()) {
  const limite = agora.getTime() - cfg.horas * 3600 * 1000;
  const cidades = (cfg.cidades || []).map(semAcento);
  const estat = { recebidas: 0, duplicadas: 0, antigas: 0, fora_do_modelo: 0, excluidas: 0, aprovadas: 0 };
  const vistas = new Set();
  const aprovadas = [];
  for (const resposta of respostas) {
    for (const bruta of resposta.data || []) {
      estat.recebidas += 1;
      const vaga = normalizarVaga(bruta);
      if (vistas.has(vaga.id)) { estat.duplicadas += 1; continue; }  // a mesma vaga aparece em vários termos
      vistas.add(vaga.id);
      if (!vaga.publicada || new Date(vaga.publicada).getTime() < limite) { estat.antigas += 1; continue; }
      // Remoto vale de qualquer lugar; híbrido e presencial só nas cidades escolhidas.
      const naCidade = cidades.includes(semAcento(vaga.cidade));
      const aceita = cfg.modelos.includes(vaga.modelo) && (vaga.modelo === "remoto" || naCidade);
      if (!aceita) { estat.fora_do_modelo += 1; continue; }
      if ((cfg.excluir || []).some((termo) => contemTermo(vaga.titulo, termo))) { estat.excluidas += 1; continue; }
      aprovadas.push(vaga);
    }
  }
  estat.aprovadas = aprovadas.length;
  return { vagas: aprovadas, estatisticas: estat };
}

const cfg = $('Configuração').first().json;
const { vagas, estatisticas } = filtrarVagas($input.all().map((i) => i.json), cfg);
if (!vagas.length) return [{ json: { _vazio: true, _estatisticas: estatisticas } }];
return vagas.map((v) => ({ json: { ...v, _estatisticas: estatisticas } }));

// Junta as vagas filtradas com a nota do ats-match, ranqueia e monta o resumo do dia.
// Roda dentro de um nó Code do n8n (o build injeta este arquivo) e nos testes com node --test.

const LIMITE_TELEGRAM = 4000; // a API do Telegram aceita até 4096 caracteres por mensagem

function escaparMarkdown(texto) {
  return String(texto).replace(/([_*[\]()~`>#+\-=|{}.!\\])/g, "\\$1"); // MarkdownV2
}

function ranquear(vagas, notas, cfg) {
  const juntas = vagas.map((vaga, i) => {
    const nota = notas[i] || {};
    return {
      ...vaga,
      descricao: undefined,
      nota: typeof nota.score === "number" ? nota.score : null,
      faltando: nota.missing_required || [],
      atendidas: nota.matched_required || [],
    };
  });
  const comNota = juntas.filter((v) => v.nota !== null && v.nota >= cfg.nota_minima);
  const semNota = juntas.filter((v) => v.nota === null).length; // ats-match fora do ar ou vaga sem descrição
  comNota.sort((a, b) => b.nota - a.nota || String(b.publicada).localeCompare(String(a.publicada)));
  return { vagas: comNota.slice(0, cfg.maximo), abaixo_da_nota: juntas.length - comNota.length - semNota, sem_nota: semNota };
}

function mensagemTelegram(ranking, data) {
  const linhas = [`*Radar de vagas · ${escaparMarkdown(data)}*`, ""];
  if (!ranking.vagas.length) linhas.push(escaparMarkdown("Nenhuma vaga nova acima da nota mínima hoje."));
  for (const v of ranking.vagas) {
    const falta = v.faltando.length ? `\n   falta: ${escaparMarkdown(v.faltando.slice(0, 3).join(", "))}` : "";
    const linha = `*${v.nota}* · [${escaparMarkdown(v.titulo)}](${v.link})\n   ${escaparMarkdown(v.empresa)} · ${escaparMarkdown(v.modelo)}${falta}`;
    if (linhas.join("\n").length + linha.length > LIMITE_TELEGRAM) break;
    linhas.push(linha);
  }
  return linhas.join("\n");
}

function montarResumo(vagas, notas, estatisticas, cfg, agora = new Date()) {
  const ranking = ranquear(vagas, notas, cfg);
  const data = agora.toISOString().slice(0, 10);
  return {
    data,
    gerado_em: agora.toISOString(),
    termos: cfg.termos,
    estatisticas: { ...estatisticas, abaixo_da_nota: ranking.abaixo_da_nota, sem_nota: ranking.sem_nota },
    vagas: ranking.vagas,
    telegram: mensagemTelegram(ranking, data),
  };
}

const cfg = $('Configuração').first().json;
const filtradas = $('Filtrar vagas').all().map((i) => i.json);
const vagas = filtradas.filter((v) => !v._vazio);
const notas = vagas.length ? $input.all().map((i) => i.json) : [];
return [{ json: montarResumo(vagas, notas, filtradas[0]._estatisticas, cfg) }];
